UPDATE contract_template_versions 
SET content_template = '<div style="font-family: Times New Roman, Times, serif; color: #111; line-height: 1.6;"><div style="text-align: center; margin-bottom: 24px;"><h3 style="margin: 0; text-transform: uppercase; font-size: 15px; font-weight: bold;">CONG HOA XA HOI CHU NGHIA VIET NAM</h3><p style="margin: 2px 0 0; font-size: 14px; text-decoration: underline; font-weight: bold;">Doc lap - Tu do - Hanh phuc</p></div><h2 style="text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 20px; text-transform: uppercase;">THOA THUAN HOP DONG THUC TAP</h2><p>Can cu theo nhu cau tiep nhan thuc tap va nang luc cua ung vien, chung toi gom co:</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">BEN A: BEN TIEP NHAN THUC TAP (CONG TY)</h4><p>- Dai dien: Phong Quan Tri Nhan Su</p><p>- Bo phan tiep nhan: {{contract.department}}</p><p>- Nguoi huong dan truc tiep: {{contract.supervisor}}</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">BEN B: THUC TAP SINH</h4><p>- Ho va ten: {{intern.fullName}}</p><p>- Ma so dinh danh / CCCD: {{intern.cccd}}</p><p>- Email lien he: {{intern.email}}</p><p>- So dien thoai: {{intern.phone}}</p><p>- Truong dao tao: {{intern.university}}</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">DIEU 1: VI TRI VA THOI GIAN THUC TAP</h4><p>- Vi tri thuc tap: {{contract.position}}</p><p>- Thoi han: Tu ngay {{contract.startDate}} den het ngay {{contract.endDate}}.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">DIEU 2: PHU CAP VA CHE DO DAO TAO</h4><p>- Muc phu cap ho tro hang thang: {{contract.allowance}}.</p><p>- Muc ho tro tren can cu theo ket qua cham cong va danh gia chuyen can trong ky thuc tap.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">DIEU 3: QUYEN HAN VA TRACH NHIEM BAO MAT</h4><p>- Tuan thu nghiem ngat noi quy lao dong, quy che an toan thong tin va van hoa doanh nghiep cua Cong ty.</p><p>- Bao mat tuyet doi moi thong tin ky thuat, ma nguon, tai lieu du an va bi mat kinh doanh ca trong va sau thoi gian thuc tap.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">DIEU 4: DIEU KHOAN BO SUNG VA THI HANH</h4><p>- Thoa thuan rieng (neu co): {{contract.customTerms}}</p><p>- Hai ben cam ket thuc hien dung cac noi dung da thoa thuan. Hop dong co hieu luc ke tu ngay ky.</p><div style="margin-top: 40px; display: flex; justify-content: space-between; text-align: center;"><div style="width: 45%;"><p style="font-weight: bold; margin-bottom: 60px;">DAI DIEN BEN A</p><p>(Ky, ghi ro ho ten)</p></div><div style="width: 45%;"><p style="font-weight: bold; margin-bottom: 60px;">DAI DIEN BEN B</p><p><strong>{{intern.fullName}}</strong></p></div></div></div>'
WHERE id = 1;
